#include <functional>
#include <string>
#include <vector>

class Allocator
{
public:
    explicit Allocator(int failAt) {}
    int allocate(std::size_t bytes) { return 0; }
    void free(int handle) {}
    int outstanding() const { return 0; }
    int calls() const { return 0; }
};

using Init = std::function<bool(Allocator&, std::vector<int>& kept)>;
std::string checkFailurePaths(const Init& init) { return ""; }

solution.solution.cpp:
#include <functional>
#include <set>
#include <string>
#include <vector>

class Allocator
{
public:
    explicit Allocator(int failAt) : m_failAt{ failAt } {}

    int allocate(std::size_t)
    {
        const int call{ m_calls++ };
        if (call == m_failAt) return 0;
        const int h{ m_next++ };
        m_live.insert(h);
        return h;
    }

    void free(int handle) { m_live.erase(handle); }
    int outstanding() const { return static_cast<int>(m_live.size()); }
    int calls() const { return m_calls; }

private:
    int m_failAt;
    int m_calls{ 0 };
    int m_next{ 1 };
    std::set<int> m_live;
};

using Init = std::function<bool(Allocator&, std::vector<int>& kept)>;

std::string checkFailurePaths(const Init& init)
{
    Allocator clean{ -1 };
    std::vector<int> kept;
    if (!init(clean, kept)) return "fails without injected failures";
    const int n{ clean.calls() };
    for (int h : kept) clean.free(h);
    if (clean.outstanding() != 0) return "leak on success";

    for (int i{ 0 }; i < n; ++i)
    {
        Allocator failing{ i };
        std::vector<int> k;
        if (init(failing, k)) return "succeeded although allocation " + std::to_string(i) + " failed";
        if (failing.outstanding() != 0) return "leak when allocation " + std::to_string(i) + " fails";
    }
    return "all " + std::to_string(n) + " failure paths clean";
}

unitTests:
bool goodInit(Allocator& a, std::vector<int>& kept) {
    const int ctx = a.allocate(64); if (!ctx) return false;
    const int ring = a.allocate(4096); if (!ring) { a.free(ctx); return false; }
    const int name = a.allocate(32); if (!name) { a.free(ring); a.free(ctx); return false; }
    kept = { ctx, ring, name }; return true;
}
bool leakyInit(Allocator& a, std::vector<int>& kept) {
    const int ctx = a.allocate(64); if (!ctx) return false;
    const int ring = a.allocate(4096); if (!ring) return false;              // forgets ctx
    kept = { ctx, ring }; return true;
}
bool ignoresFailure(Allocator& a, std::vector<int>& kept) { const int x = a.allocate(8); const int y = a.allocate(8); kept = { x, y }; return true; }
bool keepsTooLittle(Allocator& a, std::vector<int>& kept) { const int x = a.allocate(8); if (!x) return false; const int y = a.allocate(8); if (!y) { a.free(x); return false; } kept = { x }; return true; }
TEST("the allocator") { Allocator a{ 1 }; CHECK(a.allocate(1) > 0); CHECK_EQ(a.allocate(1), 0); CHECK(a.allocate(1) > 0); CHECK_EQ(a.calls(), 3); CHECK_EQ(a.outstanding(), 2); }
TEST("clean init") { CHECK_EQ(checkFailurePaths(goodInit), std::string("all 3 failure paths clean")); }
TEST("finding the bugs") {
    CHECK_EQ(checkFailurePaths(leakyInit), std::string("leak when allocation 1 fails"));
    CHECK_EQ(checkFailurePaths(ignoresFailure), std::string("succeeded although allocation 0 failed"));
    CHECK_EQ(checkFailurePaths(keepsTooLittle), std::string("leak on success"));
    CHECK_EQ(checkFailurePaths([](Allocator&, std::vector<int>&) { return false; }), std::string("fails without injected failures"));
}

